"""The agent runtime's product-analytics events (probe-contracts' catalog)."""

from __future__ import annotations

from probe.foundation.compat.compat import StrEnum


class Event(StrEnum):
    """Every product event name the CLI, SDK, daemon, service and MCP send:
    `track(Event.OUTBOX_STUCK, ...)`. A member equals its wire string, so it and its EVENT_*
    constant are interchangeable; values never change.
    """

    # --- Install wizard ---
    WIZARD_INVOKED = "wizard.invoked"
    WIZARD_STARTED = "wizard.started"
    WIZARD_ACTION_CHOSEN = "wizard.action_chosen"
    WIZARD_CONFIGURE_STARTED = "wizard.configure_started"
    WIZARD_SIGNED_IN = "wizard.signed_in"
    WIZARD_CONFIGURE_COMPLETED = "wizard.configure_completed"
    INTEGRATION_REINSTALL_STARTED = "wizard.integration_reinstall_started"
    INTEGRATION_REINSTALL_COMPLETED = "wizard.integration_reinstall_completed"

    # --- Folder import (backfill) ---
    BACKFILL_INVOKED = "backfill.invoked"
    BACKFILL_STARTED = "backfill.started"
    BACKFILL_SCANNED = "backfill.scanned"
    BACKFILL_PLAN_READY = "backfill.plan_ready"
    BACKFILL_APPROVED = "backfill.approved"
    #: Also carries the import's coding-agent props per lane
    #: (`probe.cli.imports.agent_settings.Meter.properties`), as does `import_job.finished`: listed
    #: in agent DESIGN.md (events.py).
    BACKFILL_SUMMARY = "backfill.summary"

    # --- Guided install, removal and sign-out ---
    #: `backfill.summary` and `import_job.finished` also carry the import's coding-agent props per
    #: lane (`probe.cli.imports.agent_settings.Meter.properties`): listed in DESIGN.md (events.py).
    #: The guided install settled: every selected coding agent done. Once per install, unlike
    #: `configure_completed` (once per configure CALL).
    WIZARD_INSTALL_SETTLED = "wizard.install_settled"
    #: The post-install import offer, answered. The EMPTY set (skip, the most common answer) is sent
    #: too, or the skip would be invisible.
    WIZARD_IMPORTS_CHOSEN = "wizard.imports_chosen"
    #: The dashboard handoff page: the last screen of the guided install.
    WIZARD_ONBOARDING_COMPLETED = "wizard.onboarding_completed"
    #: Removal, client side: the only record of the DECISION (a confirmation backed out of reaches
    #: no server; `client.uninstalled` / `client.device_disconnected` see only removals done).
    WIZARD_UNINSTALL_STARTED = "wizard.uninstall_started"
    WIZARD_UNINSTALL_COMPLETED = "wizard.uninstall_completed"
    #: Sign out (wizard Account, `--action logout`, the Mac app): credentials released, plugins
    #: kept. The server sees only a revoked token. Sent after release, identity pinned before (as
    #: Uninstall).
    WIZARD_SIGNED_OUT = "wizard.signed_out"
    #: The Who records row switched the daemon on or off: its adoption funnel, the only switch
    #: (Richard 2026-09-29). `recorder`: where it went; `outcome`: `RecorderOutcome`, refusals
    #: included.
    WIZARD_RECORDER_CHANGED = "wizard.recorder_changed"
    #: Session transcripts were switched on or off (`probe capture`, the wizard row, the app,
    #: `--no-capture`): `state` (`on`/`off`), `by` (`SwitchedBy`: person/agent/app), `agents`,
    #: `outcome` (`done`/`failed`/`cancelled`). A chosen off, so nobody reads it as a fault.
    CAPTURE_SWITCHED = "capture.switched"

    # --- Past sessions and import jobs ---
    #: The past-sessions lane's verdict; not `backfill.summary`, whose properties are folder-shaped
    #: and whose insights count folder imports.
    TRANSCRIPTS_SUMMARY = "transcripts.summary"
    #: Durable background imports. `kind` (transcripts|folder) is the breakdown.
    IMPORT_JOB_ENQUEUED = "import_job.enqueued"
    #: A running import that has stopped making progress -- and, unlike `finished`, a LEVEL rather
    #: than an edge, so it is rate-limited at the call site.
    IMPORT_JOB_STALLED = "import_job.stalled"
    #: The terminal state, from the worker itself. THIS is "did the import finish":
    #: `backfill.summary` fires at hand-off, reporting `partial` with 0% coverage for everything
    #: queued.
    IMPORT_JOB_FINISHED = "import_job.finished"
    #: Approved imports thrown away without finishing -- by Uninstall, or by the wizard's explicit
    #: Exit. Work someone asked for and will not get.
    IMPORT_JOB_CLEARED = "import_job.cleared"

    # --- Outbox ---
    #: One drain episode ended. The happy path too: without that baseline a silent fleet and one
    #: whose workers all died look the same.
    OUTBOX_DRAINED = "outbox.drained"
    #: A stuck (not busy) queue, from the FOREGROUND banner: `maybe_spawn` forks no drainer while
    #: one is auth-blocked or paused, so the next `probe` command is the only process that sees it.
    OUTBOX_STUCK = "outbox.stuck"
    #: Writes stranded under a dead credential of the signed-in account, sent with the login
    #: (`journal.rescue_stranded`): an `auth_blocked` `outbox.stuck` fixing itself.
    OUTBOX_RESCUED = "outbox.rescued"
    #: Queued or dead-lettered writes moved to `discarded/` (`probe outbox discard`, or out of
    #: cleanup by `journal.relocate_discards`): else a vanished backlog reads as sent (Bucket,
    #: 2026-10-23).
    OUTBOX_DISCARDED = "outbox.discarded"
    #: A one-time restore put back writes set aside behind one revoked key
    #: (`journal.restore_set_aside`, Bucket 2026-10-22/23): how many, what stayed aside and why,
    #: what the login check refused or put off. The delivery shows in `outbox.rescued`.
    OUTBOX_RESTORED = "outbox.restored"
    #: The CLI's every-command check lifted a stale pause (end passed, or an older CLI's endless
    #: one; `outbox_worker.lift_stale_pause`). The Probe service lifts too; only `outbox.drained`
    #: reports it.
    OUTBOX_PAUSE_LIFTED = "outbox.pause_lifted"

    # --- Staff requests, training processes and reports ---
    #: Staff's one-time capture repair ran here (control/073,
    #: `probe.cli.lifecycle.notices.capture_repair._capture_repair_notice`): `applied` (credentials
    #: written, locks lifted) or `write_failed`. Agent slugs and counts only.
    CAPTURE_REPAIR_APPLIED = "capture.repair_applied"
    #: Staff's one-time settings change ran here (control/074,
    #: `probe.cli.lifecycle.remote_settings`): setting, value, default moved, sessions switched,
    #: report taken. Never a session id.
    SETTINGS_REMOTE_APPLIED = "settings.remote_applied"
    #: A TRAINING process's delivery counts (plan 1.12), every 15 min and at each run's close:
    #: deltas, counts only (never a key, body, name or path), so we see loss before a customer does.
    DELIVERY_SUMMARY = "sdk.delivery.summary"
    #: An automatic report (`probe.core.report`) the API refused with every credential here: such a
    #: machine's one way to reach us. Posted to #eng-alerts by PostHog. Slugs only.
    REPORT_UNDELIVERABLE = "service.report_undeliverable"
    #: The daemon hit an error an engineer should look at (`probe.daemon.alerts`). A PostHog
    #: destination posts it to #eng-alerts.
    DAEMON_ERROR = "daemon.error"

    # --- Probe service ---
    # The Probe service's own events: `probe.service.watch.statepost` sends them through
    # `emit_service_event`, the only door they have (`SERVICE_EVENTS`).
    #: The Probe service's own events (`probe.service.watch.statepost` sends them through
    #: `emit_service_event`, the only door they have).
    SERVICE_STARTED = "service.started"
    SERVICE_STATE = "service.state"
    SERVICE_STOPPED = "service.stopped"
    LIFEBOAT_ACTED = "lifeboat.acted"

    # --- Updates ---
    #: An update found no `uv`, or only an older copy of Probe's own (a raised pinned version), and
    #: tried to install the pinned one (`probe.service.updater.uv.ensure_uv`): `outcome`
    #: (`PrivateUvOutcome`: installed | failed), `reason` when failed (`PrivateUvReason`, a closed
    #: set, never a host, path or URL: unsupported_machine, no_wheel, no_hash, unpinned,
    #: index_hash_not_pinned, download_hash_mismatch, bad_index_url, too_large, http_4xx, http_5xx,
    #: network, extract_failed, bad_version, toml_unreadable, other), `uv_version`, `index` (pypi |
    #: configured). At most one try per 6 h per machine. Confirms the zero-touch fix per machine.
    UPDATES_PRIVATE_UV = "updates.private_uv"

    # --- Hosted MCP ---
    #: The hosted MCP's per-tool accounting event (`probe.mcp.delivery.accounting`, its own sender).
    MCP_TOOL_SERVED = "mcp.tool_served"

    # --- Install refusals ---
    # Every front door that refuses to install says so once, so a person stuck on an unsupported
    # platform reaches us (a PostHog destination posts it to #probe-usage).
    #: Someone tried to install Probe where it does not run (Windows). Carries `surface`
    #: (`dashboard`, `cli`, `launcher`) and `os`; the dashboard's carries the signed-in person, once
    #: per Install step it showed. A demand signal, not breakage.
    INSTALL_UNSUPPORTED_PLATFORM = "install.unsupported_platform"

    # --- Errors ---
    #: One crash or swallowed exception, in PostHog's Error Tracking shape: the client's
    #: `report_crash`, the server's `capture_exception`.
    EXCEPTION = "$exception"
